"from bs4 import BeautifulSoup\n\nwith open(\"tests/workday/Systems Software Engineer - New College Grad 2026.htm\", \"r\", encoding=\"utf-8\", errors=\"ignore\") as f:\n    soup = BeautifulSoup(f.read(), \"html.parser\")\n\ntitle_inputs = soup.select('input[id*=\"workExperience-\"][id*=\"jobTitle\"], input[name=\"jobTitle\"]')\nprint(\"Title inputs matched:\", len(title_inputs))\n\ncomp_inputs = soup.select('input[id*=\"workExperience-\"][id*=\"companyName\"], input[name=\"companyName\"]')\nprint(\"Company inputs matched:\", len(comp_inputs))\n\nloc_inputs = soup.select('input[id*=\"workExperience-\"][id*=\"location\"]')\nprint(\"Location inputs matched:\", len(loc_inputs))\n\nchk_inputs = soup.select('input[id*=\"workExperience-\"][id*=\"currentlyWorkHere\"]')\nprint(\"CurrentlyWorkHere inputs matched:\", len(chk_inputs))\n\ndesc_inputs = soup.select('textarea[id*=\"workExperience-\"]')\nprint(\"Desc inputs matched:\", len(desc_inputs))\n\n# Websites button\nheadings = [el for el in soup.find_all(['h1', 'h2', 'h3', 'h4', 'legend', 'label', 'div']) if el.get_text(strip=True).lower() == 'websites']\nfor h in headings:\n    container = h.find_parent(['div', 'fieldset', 'form'])\n    if container:\n        btns = container.find_all('button')\n        for b in btns:\n            print(\"Websites button found:\", b.get_text(strip=True), b.get('data-automation-id'))\n"